// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        address bob = address(0x456);
        vm.prank(bob);
        // The caller must be the current owner to pass onlyOwner modifier.
        // After deploy, owner is msg.sender (this test contract). So first transfer to bob.
        c.setOwner(bob);
        // Now bob is owner, call setOwner(alice)
        vm.prank(bob);
        c.setOwner(alice);
        // In correct contract: owner = alice; in bug: owner = msg.sender = bob
        assertTrue(c.owner() == alice);
    }
}

