pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // owner is the contract deployer (this contract in test)
        address newOwner = address(0x123);
        // call setOwner as owner (the default msg.sender in test is this contract)
        c.setOwner(newOwner);
        // In reference, owner becomes newOwner; in mutant, require(false) reverts so owner stays as this contract
        assertTrue(c.owner() == newOwner); // reference: true; mutant: false (owner is still this contract)
    }
}

